from pyspark.errors import AnalysisException

path = "/tmp/landing/2026-03-08"
looks = {"n": 0}


def read_day():
    looks["n"] += 1
    if looks["n"] == 3:  # the carrier's upload finishes just before the third look
        shipment_events.filter(F.col("load_date") == "2026-03-08").write.mode("overwrite").parquet(path)
    return spark.read.parquet(path)


def not_landed_yet(e):
    return isinstance(e, AnalysisException) and e.getCondition() == "PATH_NOT_FOUND"


def with_retries(step, attempts, retry_if):
    for attempt in range(1, attempts + 1):
        try:
            result = step()
            print("attempt", attempt, "worked")
            return result
        except Exception as e:
            if not retry_if(e) or attempt == attempts:
                print("attempt", attempt, "failed, giving up")
